from typing import List, Union, Optional


class PrettyNode:
    """ Represents collapsable node inside pretty_log.html file which was created using @pretty_log decorator. """

    def __init__(self):
        self._parent: Optional[PrettyNode] = None
        self._name: Optional[str] = None
        self._library: Optional[str] = None
        self._arguments: Optional[str] = None
        self._start_time: Optional[str] = None
        self._end_time: Optional[str] = None
        self._execution_status: Optional[str] = None
        self._content: List[Union[PrettyNode, str]] = []

    def __str__(self):
        str_repr = f'<kw name="{self.name}" library="{self.library}">\n' \
                   f'<msg timestamp="{self.start_time}" level="TRACE">Arguments: {self.arguments}</msg>\n'
        for content in self._content:
            str_repr += str(content)
        str_repr += f'<status status="{self.execution_status}" starttime="{self.start_time}" endtime="{self.end_time}"></status>\n' \
                    f'</kw>\n'
        return str_repr

    @property
    def parent(self) -> 'PrettyNode':
        """ Returns parent pretty node of this pretty node. """
        return self._parent

    @parent.setter
    def parent(self, parent: 'PrettyNode'):
        """ Sets given pretty node as a parent of this pretty node. """
        self._parent = parent

    @property
    def name(self) -> str:
        """ Returns name of this pretty node which is a name of a function decorated with @pretty_log. """
        return self._name

    @name.setter
    def name(self, name: str):
        """ Sets name of this pretty node which is a name of a function decorated with @pretty_log. """
        self._name = name

    @property
    def library(self) -> str:
        """ Returns name of a module where function decorated with @pretty_log was implemented. """
        return self._library

    @library.setter
    def library(self, library: str):
        """ Sets name of a module where function decorated with @pretty_log was implemented. """
        self._library = library

    @property
    def arguments(self) -> str:
        """ Returns list of arguments used when function decorated with @pretty_log was called. """
        return self._arguments

    @arguments.setter
    def arguments(self, arguments: str):
        """ Sets list of arguments used when function decorated with @pretty_log was called. """
        self._arguments = arguments

    @property
    def start_time(self) -> str:
        """ Returns start time of this pretty node. """
        return self._start_time

    @start_time.setter
    def start_time(self, start_time: str):
        """ Sets start time of this pretty node. """
        self._start_time = start_time

    @property
    def end_time(self) -> str:
        """ Returns end time of this pretty node. """
        return self._end_time

    @end_time.setter
    def end_time(self, end_time: str):
        """ Sets end time of this pretty node. """
        self._end_time = end_time

    @property
    def execution_status(self) -> Optional[str]:
        """ Returns execution status of this pretty node, can be either 'PASS', 'FAIL' or None (execution status is not yet known). """
        if self._content and any(child.execution_status == 'FAIL' for child in self._content if isinstance(child, PrettyNode)):
            self._execution_status = 'FAIL'
        return self._execution_status

    @execution_status.setter
    def execution_status(self, execution_status: Optional[str]):
        """ Sets execution status of this pretty node, can be either 'PASS', 'FAIL' or None (execution status is not yet known). """
        self._execution_status = execution_status

    @property
    def descendants(self) -> List['PrettyNode']:
        """ Returns all descendant pretty nodes (children, children's children, etc.) of this pretty node. """
        descendants = []

        for child in self._content:
            if isinstance(child, PrettyNode):
                descendants.append(child)
                descendants.extend(child.descendants)

        return descendants

    @property
    def latest_failed_node(self) -> Optional['PrettyNode']:
        """ Returns newest pretty node with 'FAIL' execution status. Can be either this pretty node or one of its descendants. """
        failed_descendants = [descendant for descendant in self.descendants if descendant.execution_status == 'FAIL']

        if failed_descendants:
            return failed_descendants[-1]
        elif self._execution_status == 'FAIL':
            return self
        else:
            return None

    def add(self, item: Union['PrettyNode', str]):
        """
        Adds new item into this pretty node content.
        :param item: can be either:
                     * other pretty node (which will become this pretty node's child)
                     * plain log entry as a string
        """
        self._content.append(item)
